import{_ as t,o as a,c as n,a0 as s}from"./chunks/framework.ChlVJx0I.js";const p=JSON.parse('{"title":"Skill command normalizes the injected skill command separator","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0033-skill-command-normalizes-the-injected-skill-command-separator.md","filePath":"adr/0033-skill-command-normalizes-the-injected-skill-command-separator.md","lastUpdated":1791379912000}'),o={name:"adr/0033-skill-command-normalizes-the-injected-skill-command-separator.md"};function i(l,e,r,d,c,m){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="skill-command-normalizes-the-injected-skill-command-separator" tabindex="-1">Skill command normalizes the injected skill command separator <a class="header-anchor" href="#skill-command-normalizes-the-injected-skill-command-separator" aria-label="Permalink to &quot;Skill command normalizes the injected skill command separator&quot;">​</a></h1><p>pi expands a <code>/skill:name args</code> command by parsing the name up to the <strong>first space</strong> in the text, then looking the name up in its skill list. A skill command whose name and arguments are separated by a <strong>newline</strong> - the shape injected prompts arrive in, because the factory&#39;s consultation templates put the command on its own line and the body below it - therefore fails the lookup: the parsed &quot;name&quot; is the name plus the newlines plus the start of the argument text, nothing matches, and pi passes the text through unexpanded. The recorded user message still starts with the literal <code>/skill:</code> line. When the skill also carries <code>disable-model-invocation: true</code> (as <code>grill-with-docs</code> does), it is absent from the system prompt&#39;s skills section as well, so the model gets no pointer to the skill at all and must hunt the filesystem for the SKILL.md before it can follow the injected instructions (issue #126, session 01a112ff).</p><p>We decided: a small extension, skill-command, registers an <code>input</code> handler - the event pi fires on every submitted prompt, before its own skill and template expansion - and performs exactly one rewrite. When the text starts with <code>/skill:name</code> and the separator between the name and the arguments contains a newline, the separator becomes a single space; the arguments keep their remaining bytes. pi&#39;s built-in expansion then runs on the normalized text and stays the owner of the expansion: the lookup, the SKILL.md read, the frontmatter strip, the <code>&lt;skill name=... location=...&gt;</code> block, and the error path. The extension never reads a SKILL.md itself.</p><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h2><ul><li><strong>Expand the skill command inside the extension</strong> (read the SKILL.md, strip the frontmatter, build the block). Rejected because it duplicates pi&#39;s expansion and would drift silently from pi&#39;s format; it also needs a skill list the extension context does not expose, so it could not resolve skills pi resolves.</li><li><strong>Change the factory&#39;s templates to a space-separated command</strong> (<code>/skill:name &lt;body&gt;</code> on one line). Rejected because the templates are multi-line documents where the command is the first line; cramming the body onto that line is unreadable, and the break is in the parser&#39;s tolerance, not in the document&#39;s shape. It also fixes only this one producer, while any other newline injection (an operator pasting a multi-line command into the TUI) would still break.</li><li><strong>Patch pi upstream.</strong> The one-line parser fix belongs upstream and may land there; this extension makes the injection shape work on the pi versions in use today, and it degrades to a no-op on any future pi that accepts newline separators.</li><li><strong>Drop <code>disable-model-invocation</code> from the affected skills.</strong> Rejected because the flag is the upstream&#39;s deliberate choice (the skill is a command, not an auto-selected one), and the expansion failure happens for every injected command, flagged or not: the flag only decides whether the model can find the file as a fallback, not whether the command expands.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Every prompt that starts with <code>/skill:name</code> followed by a newline separator is rewritten before expansion, in every session the package is installed in, whatever the source (interactive, rpc, extension).</li><li>The rewrite is whitespace-only in its visible effect: pi trims the arguments when it expands, so the recorded message is byte-identical to what a space-separated command would have produced.</li><li>Commands pi already parses (space separator, bare name) and all non-skill text pass through untouched; an unknown skill name with a newline separator is normalized but still fails pi&#39;s lookup and passes through, as before.</li><li>A tab-only separator is out of scope: no producer injects it, and normalizing it would touch input pi does not claim.</li><li>If pi upstream ever accepts newline separators natively, the extension&#39;s rewrite becomes invisible: it rewrites the input to the form pi parses today, which a more tolerant pi still parses.</li></ul>',7)])])}const u=t(o,[["render",i]]);export{p as __pageData,u as default};
